// src/pages/Login.js
import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { Building2 } from 'lucide-react';

export default function Login() {
  const { login, loading } = useAuth();
  const navigate = useNavigate();
  const [form, setForm] = useState({ email: '', password: '' });
  const [error, setError] = useState('');

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    try {
      const user = await login(form.email, form.password);
      if (user.role === 'CLIENT') navigate('/my-loan');
      else navigate('/dashboard');
    } catch (err) {
      setError(err.response?.data?.message || 'Erreur de connexion');
    }
  };

  return (
    <div style={{
      minHeight: '100vh', display: 'flex',
      background: 'linear-gradient(135deg, var(--primary) 0%, #0d2137 100%)',
    }}>
      {/* Left panel */}
      <div style={{
        flex: 1, alignItems: 'center', justifyContent: 'center',
        padding: 40, display: window.innerWidth < 768 ? 'none' : 'flex',
      }}>
        <div style={{ color: '#fff', maxWidth: 380 }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 32 }}>
            <div style={{ width: 48, height: 48, background: 'var(--accent)', borderRadius: 12, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
              <Building2 size={24} color="#fff" />
            </div>
            <span style={{ fontFamily: 'var(--font-heading)', fontSize: 24, fontWeight: 700 }}>MLMS</span>
          </div>
          <h1 style={{ fontFamily: 'var(--font-heading)', fontSize: 36, fontWeight: 700, lineHeight: 1.2, marginBottom: 16 }}>
            Microfinance<br />Loan Management
          </h1>
          <p style={{ color: 'rgba(255,255,255,0.6)', fontSize: 15, lineHeight: 1.7 }}>
            Gérez vos clients, prêts et remboursements en toute simplicité.
          </p>
          <div style={{ marginTop: 40, display: 'flex', flexDirection: 'column', gap: 14 }}>
            {['Gestion complète des clients', 'Calcul automatique des intérêts', 'Calendrier de remboursement', 'Tableau de bord en temps réel'].map(f => (
              <div key={f} style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                <div style={{ width: 6, height: 6, borderRadius: '50%', background: 'var(--accent)' }} />
                <span style={{ fontSize: 14, color: 'rgba(255,255,255,0.7)' }}>{f}</span>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Right panel - form */}
      <div style={{
        width: '100%', maxWidth: 440,
        background: '#fff', display: 'flex',
        alignItems: 'center', justifyContent: 'center', padding: 40,
      }}>
        <div style={{ width: '100%', maxWidth: 360 }}>
          <div style={{ marginBottom: 32 }}>
            <h2 style={{ fontFamily: 'var(--font-heading)', fontSize: 24, color: 'var(--gray-900)', marginBottom: 6 }}>
              Connexion
            </h2>
            <p style={{ color: 'var(--gray-500)', fontSize: 13 }}>Accédez à votre espace de gestion</p>
          </div>

          {error && <div className="alert alert-danger">{error}</div>}

          <form onSubmit={handleSubmit}>
            <div className="form-group">
              <label>Email</label>
              <input className="form-control" type="email" placeholder="admin@mlms.com"
                value={form.email} onChange={e => setForm({ ...form, email: e.target.value })} required />
            </div>
            <div className="form-group">
              <label>Mot de passe</label>
              <input className="form-control" type="password" placeholder="••••••••"
                value={form.password} onChange={e => setForm({ ...form, password: e.target.value })} required />
            </div>
            <button type="submit" className="btn btn-primary" disabled={loading}
              style={{ width: '100%', justifyContent: 'center', padding: '11px', fontSize: 14, marginTop: 8 }}>
              {loading ? <><div className="spinner" style={{ width: 16, height: 16, borderWidth: 2 }} /> Connexion...</> : 'Se connecter'}
            </button>
          </form>

          <div style={{ marginTop: 32, padding: 16, background: 'var(--gray-50)', borderRadius: 10, border: '1px solid var(--gray-200)' }}>
            <p style={{ fontSize: 11, fontWeight: 600, color: 'var(--gray-500)', textTransform: 'uppercase', letterSpacing: 0.5, marginBottom: 10 }}>Comptes de test</p>
            {[
              { role: 'Admin', email: 'admin@mlms.com' },
              { role: 'Agent', email: 'officer@mlms.com' },
              { role: 'Client', email: 'ali.client@mlms.com' },
            ].map(({ role, email }) => (
              <div key={email} onClick={() => setForm({ email, password: 'secret123' })}
                style={{ display: 'flex', justifyContent: 'space-between', padding: '6px 0', cursor: 'pointer', borderBottom: '1px solid var(--gray-200)' }}
                className="test-account">
                <span style={{ fontSize: 12, fontWeight: 600, color: 'var(--primary)' }}>{role}</span>
                <span style={{ fontSize: 11, color: 'var(--gray-500)' }}>{email}</span>
              </div>
            ))}
            <p style={{ fontSize: 11, color: 'var(--gray-400)', marginTop: 8 }}>Mot de passe : secret123 — cliquer pour remplir</p>
          </div>
        </div>
      </div>
    </div>
  );
}
